package com.bookeat.notification.controller;
import com.bookeat.common.response.*;import com.bookeat.security.AppPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.access.prepost.PreAuthorize;import lombok.RequiredArgsConstructor;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import java.util.*;
@RestController @RequiredArgsConstructor @SecurityRequirement(name="bearerAuth")
public class NotificationController {
private final com.bookeat.notification.service.NotificationService service;
 public record BroadcastRequest(@NotBlank @Size(max=160) String title,@NotBlank @Size(max=2000) String message,@NotBlank @Size(max=60) String type,@NotBlank String audience,List<UUID> recipientIds) {}
 public record BroadcastResponse(int recipientCount) {}
 @GetMapping("/api/v1/customer/notifications") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="List own in-app notifications",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.notification.dto.NotificationResponse>> op0(@AuthenticationPrincipal AppPrincipal p,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("List own in-app notifications",service.list(p.userId(),page,size));}
 @PutMapping("/api/v1/customer/notifications/{id}/read") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Mark own notification read",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<Void> op1(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id){service.read(p.userId(),id);return ApiResponse.ok("Mark own notification read",null);}
 @PutMapping("/api/v1/customer/notifications/read-all") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Mark all own notifications read",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<Void> op2(@AuthenticationPrincipal AppPrincipal p){service.readAll(p.userId());return ApiResponse.ok("Mark all own notifications read",null);}
 @GetMapping("/api/v1/owner/notifications") @PreAuthorize("hasRole('OWNER')") @Operation(summary="List own in-app notifications",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.notification.dto.NotificationResponse>> op3(@AuthenticationPrincipal AppPrincipal p,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("List own in-app notifications",service.list(p.userId(),page,size));}
 @PutMapping("/api/v1/owner/notifications/{id}/read") @PreAuthorize("hasRole('OWNER')") @Operation(summary="Mark own notification read",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<Void> op4(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id){service.read(p.userId(),id);return ApiResponse.ok("Mark own notification read",null);}
 @PutMapping("/api/v1/owner/notifications/read-all") @PreAuthorize("hasRole('OWNER')") @Operation(summary="Mark all own notifications read",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<Void> op5(@AuthenticationPrincipal AppPrincipal p){service.readAll(p.userId());return ApiResponse.ok("Mark all own notifications read",null);}
 @PostMapping("/api/v1/admin/notifications") @PreAuthorize("hasAuthority('NOTIFICATION_MANAGE')") @Operation(summary="Send an in-app notification to customers or restaurant owners")
 public ApiResponse<BroadcastResponse> broadcast(@AuthenticationPrincipal AppPrincipal p,@Valid @RequestBody BroadcastRequest q){int count=service.broadcast(p.userId(),q.title(),q.message(),q.type(),q.audience(),q.recipientIds());return ApiResponse.ok("Notification queued",new BroadcastResponse(count));}
 @GetMapping("/api/v1/admin/notifications") @PreAuthorize("hasAuthority('NOTIFICATION_MANAGE')") @Operation(summary="List own in-app notifications",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.notification.dto.NotificationResponse>> op6(@AuthenticationPrincipal AppPrincipal p,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("List own in-app notifications",service.list(p.userId(),page,size));}
 @PutMapping("/api/v1/admin/notifications/{id}/read") @PreAuthorize("hasAuthority('NOTIFICATION_MANAGE')") @Operation(summary="Mark own notification read",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<Void> op7(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id){service.read(p.userId(),id);return ApiResponse.ok("Mark own notification read",null);}
 @PutMapping("/api/v1/admin/notifications/read-all") @PreAuthorize("hasAuthority('NOTIFICATION_MANAGE')") @Operation(summary="Mark all own notifications read",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<Void> op8(@AuthenticationPrincipal AppPrincipal p){service.readAll(p.userId());return ApiResponse.ok("Mark all own notifications read",null);}
}
